193	  frames++; const now = performance.now(); fpsT = (now - fpsLast) / 1000;
194	  if (fpsT >= 0.5) {
195	    fpsEl.textContent = String(Math.round(frames / fpsT)); fpsLast = now; callsEl.textContent = String(renderer.info.render.calls);
196	    const fs = perf.stats(); ftimeEl.textContent = `${fs.avg.toFixed(1)} · p95 ${fs.p95.toFixed(0)} · max ${fs.max.toFixed(0)}`;
197	    showEl.textContent = showLabel(); frames = 0; fpsT = 0;
198	  }
