content.content:
1	/* ============================ Tự khám phá: điều phối chế độ bay dù lượn ============================
2	   Nối flight (mô hình), glider (dù), chase (camera) với vòng animate, phím và URL.
3	   `?explore=glider` bay thẳng; không tham số (hoặc `?test&chooser`) hiện màn chọn; Esc tải lại trang không còn tham số explore. Camera do explore.update đặt sau updateCamera. */
4	import * as THREE from 'three';
5	import { scene, camera, controls, renderer } from '../core/renderer';
6	import { composer } from '../core/postprocessing';
7	import { cam, keys } from '../views/state';
8	import { exCreate, exStep, exInputFromKeys, type GliderState, type GliderInput } from './flight';
9	import { exBuildGlider, exPlaceGlider } from './glider';
10	import { plPreload, plReset, plSetWarm, plDebug } from './pilot';
11	import { exChase } from './chase';
12	import { exShowChooser } from './chooser';
13	import { exNight, exNightBind, exNightStep } from './nightShows';
14	import { show } from '../bridges/dragon/effects';
15	import { exMulti } from './multi';
16	import { stroll, setupStroll } from './stroll';
17	import { drive, setupDrive } from './drive';
18	import { bike, setupBike } from './bike';
19	import { stAvatars } from './stroll/avatars';
20	import { exWatchShow, exWatchHide, exWatchRender, exFlyNotice } from './multi/watch';
21	import { CONFIG } from '../config';
22	import type { SwingController } from '../bridges/song-han/SwingController';
23	
24	const _inp: GliderInput = { turn: 0, climb: 0, throttle: 0 };   // đầu vào tái dùng mỗi khung
25	
26	/* Làm nóng shader người treo có xương (D-018), như stroll/index.ts stRigSetWarm: hai biến thể (vẽ thẳng ra canvas ban ngày, vào render target của composer ban đêm),
27	   đèn / sương / bóng lấy từ cảnh chính, camera chính (đèn lọc theo lớp của nó). Cảnh nguồn không thêm vào scene */
28	plSetWarm(async (o: THREE.Object3D) => {
29	  const rt = renderer.getRenderTarget();
30	  renderer.setRenderTarget(null);
31	  const a = renderer.compileAsync(o, camera, scene);
32	  renderer.setRenderTarget(rt);
33	  await a;
34	  renderer.setRenderTarget(composer.readBuffer);
35	  const b = renderer.compileAsync(o, camera, scene);
36	  renderer.setRenderTarget(rt);
37	  await b;
38	});
39	
40	let glider: THREE.Group | null = null;
41	let state: GliderState | null = null;
42	let watching = false;   // đang xem người khác bay (hết chỗ hoặc vừa nhường chỗ): không có dù của mình, không đọc phím
43	let chased = false;     // camera đã bám người được xem lần nào chưa (lần đầu đặt thẳng, không trượt từ xa)
44	let readout = '';   // chữ đang hiện ở #exSpeed: chỉ ghi DOM khi đổi
45	let saved: { explore: boolean; show: boolean } | null = null;   // thứ start() đổi, stop() trả lại (như drive/index.ts): lớp body 'explore' đã có từ trước chưa, show.on của Cầu Rồng (exNightStep đổi theo trời)
46	
47	const active = () => cam.mode === 'glider' && state !== null;
48	const inGlider = () => active() || watching;   // Esc và giao diện bay áp cho cả chế độ xem
49	
50	/* Mỗi khung khi xem: dù người khác, nhãn, danh sách; camera bám dù đang xem (không có người thì giữ nguyên) */
51	function watchStep(dt: number): void {
52	  exMulti.update(dt, performance.now(), null);
53	  const st = exMulti.watchState();
54	  if (st) { exChase(camera, controls.target, st, dt, !chased); chased = true; }
55	  exNightStep(dt);
56	}
57	
58	/* Đổi phiên khi đang xem hoặc bay: vào bay, mất kết nối, bị thu hồi chỗ */
59	function onMultiChange(): void {
60	  const s = exMulti.session; if (!s) return;
61	  if (watching) {
62	    if (s.phase === 'flying') { explore.start(); return; }   // chấp nhận lời mời: cất cánh mới như bay thường
63	    if (s.phase === 'solo') { try { sessionStorage.setItem('exMpNotice', 'lost'); } catch { /* bộ nhớ bị chặn */ } explore.exit(); return; }   // màn chọn đọc cờ này và hiện exMpLost
64	    exWatchRender();
65	  } else if (active()) {
66	    if (s.phase === 'watching') { state = null; if (glider) glider.visible = false; explore.startWatching(true); return; }   // chỗ bị thu hồi: sang xem, camera giữ nguyên
67	    if (s.phase === 'solo' && s.notice === 'lost') exFlyNotice(s, 'exMpLost');   // vẫn bay, người khác đã biến mất
68	  }
69	}
70	
71	/* Đồng hồ tốc độ (km/h) và độ cao (m): chỉ số và đơn vị nên không cần dịch */
72	function exShowSpeed(): void {
73	  const t = `${Math.round(state!.speed * 3.6)} km/h · ${Math.round(state!.pos.y)} m`;
74	  if (t === readout) return;
75	  readout = t;
76	  const el = document.getElementById('exSpeed'); if (el) el.textContent = t;
77	}
78	
79	/* Một bước: mô phỏng, đặt dù, đặt camera bám */
80	function advance(dt: number, inp: GliderInput): void {
81	  exStep(state!, inp, dt);
82	  exPlaceGlider(glider!, state!, dt, inp);
83	  exChase(camera, controls.target, state!, dt);
84	  exShowSpeed();
85	  exNightStep(dt);
86	  exMulti.update(dt, performance.now(), state);   // dù người khác, nhãn tên, gửi vị trí (không làm gì khi bay một mình)
87	}
88	
89	export const explore = {
90	  active,
91	  nightShows: exNight,
92	  get state() { return state; },
93	  get glider() { return glider; },
94	  get watching() { return watching; },
95	  /* Cho test: số đo người treo của dù mình (pilot/index.ts plDebug); null khi chưa bay */
96	  pilotDebug() { return glider ? plDebug(glider) : null; },
97	  /* Tự lái (intro, D-045): khác null thì update() gọi auto(_inp) thay cho phím; bên gán ghi vào _inp, không cấp phát */
98	  auto: null as ((inp: GliderInput) => void) | null,
99	  /* at: điểm + hướng cất cánh (intro); bỏ trống thì cất cánh ở CONFIG.explore.takeoff như cũ */
100	  start(at?: { pos: [number, number, number]; yaw: number }): void {
101	    plPreload();
102	    if (watching) { watching = false; document.body.classList.remove('ex-watching'); exWatchHide(); }
103	    exMulti.onChange = onMultiChange;
104	    state = exCreate();
105	    const slot = exMulti.session ? exMulti.session.mySlot : -1;
106	    if (slot >= 0) state.pos.z += CONFIG.explore.multi.spawnSpread * (slot - 2);   // mỗi slot cất cánh lệch một đoạn để không chồng nhau
107	    if (at) { state.pos.set(at.pos[0], at.pos[1], at.pos[2]); state.yaw = at.yaw; }
108	    if (!saved) saved = { explore: document.body.classList.contains('explore'), show: show.on };
109	    if (!glider) glider = exBuildGlider();
