1	/* ============================ Lái xe: điều phối chế độ (lái một mình, máy tính) ============================
2	   Nối mạng đường (net / roadData / solids / sceneSolids), chuyển động + va chạm (motion / collide), hình xe (car / cars),
3	   camera sau xe (camera) với vòng animate, phím, chuột, cảm ứng (touch), HUD (hud: đồng hồ, bản đồ nhỏ, gợi ý), tiếng mô tơ / còi (sound). Mẫu: explore/stroll/index.ts.
4	   `?explore=drive` vào thẳng, lái một mình; thẻ "Ô tô" ở màn chọn: có máy chủ thì qua sảnh 5 chỗ lái (phiên kind 'drive'), không thì lái một mình.
5	   Esc và nút Thoát dùng explore.exit() (tải lại trang, D-020); trước đó drive.stop() trả lại các thứ đã đổi.
6	   - Mạng đường dựng MỘT lần ở lần đầu vào chế độ và giữ lại: ô tĩnh + vật cản tĩnh + nhà / chân đế thu từ cảnh (drCollectRuntime chỉ push,
7	     gọi hai lần sẽ nhân đôi vật cản). Chỉ đọc cảnh, sau mọi rand().
8	   - Barie Cầu sông Hàn: cổng DR_GATE_SWING của ô nhịp quay đóng khi cầu rời CLOSED (mỗi khung); không tự quay, không tăng tốc quay (như đi dạo).
9	     Xe đang chạm nhịp quay lúc đó được sơ tán ra ngoài barie gần nhất (motion.ts drEvacStep), gói trong thời gian còn lại trước khi nhịp xoay
10	     (drSwingBudget: coi như nhịp không phải chờ xe tự động rời nhịp, tức thời gian ngắn nhất).
11	   - Xe tự động: mỗi khung lấy hộp các xe đang hiện trong bán kính CONFIG.drive.ai.radius (common/trafficQuery.ts trNearby, mảng tái dùng);
12	     người chơi lao vào thì bị chặn, xe tự động chạy tới thì đi xuyên (collide.ts drMove).
13	   - Ban đêm Cầu Rồng tự phun như khi đi dạo (exNightStep, swing = false).
14	   - Hầm: driveView.far = CONFIG.drive.tunnelFar khi đang lái để mặt đường hầm hiện ở nút giao với hai đường dọc mới; thoát trả 1.
15	   - Xe của mình nằm trong drCars ở slot của mình (màu theo slot, multiParams.colors) hoặc slot 0 khi lái một mình; xe và bánh chỉ vào cảnh khi có xe (multi/index.ts gắn drCars.group
16	     theo exDrivers.onCars), góc nhìn cũ không thêm lệnh vẽ.
17	   - Nhiều người (exMulti, phiên kind 'drive'): xuất phát theo slot, gửi vị trí + vận tốc + góc lái sendHz lần/s (cả lúc đang sơ tán khỏi nhịp quay); xe người khác (exDrivers) không tham gia va chạm
18	     (chỉ vẽ, nhãn tên, chấm trên bản đồ nhỏ). Hết chỗ lái thì chế độ xem (startWatching): camera sau xe được xem, không điều khiển, đồng hồ + bản đồ theo xe đó; rời máy thì nhường chỗ sang xem.
19	   - Phím theo e.code (keys.ts), chỉ ghi khi đang lái, bỏ qua ô nhập và tổ hợp Ctrl / Meta / Alt; blur, ẩn tab, focus vào ô nhập thì nhả hết.
20	   - Cảm ứng (touch.ts, #drHud): đọc SAU phím và gộp (giá trị có độ lớn lớn hơn), không xóa phím trên máy lai; reset() cùng chỗ nhả phím. Phím H: còi.
21	   Mỗi khung không cấp phát (D-018). */
22	import type * as THREE from 'three';
23	import { scene, camera, controls, canvas, renderer } from '../../core/renderer';
24	import { composer, onResize } from '../../core/postprocessing';
25	import { cam } from '../../views/state';
26	import { CONFIG } from '../../config';
27	import { driveView } from '../../environment/driveRoads';
28	import { drMakeNet, drSetGate, type DrNet } from './net';
29	import { drBuildPads, DR_GATE_SWING } from './roadData';
30	import { drBuildSolids } from './solids';
31	import { drCollectRuntime, drSceneStats } from './sceneSolids';
32	import { drCreate, drStep, drEvacStep, type DrState, type DrInput } from './motion';
33	import { trNearby } from '../../common/trafficQuery';
34	import { drUseBody, DR_CAR_BODY, type DrBox } from './collide';
35	import { drCarLoad, drCarSetWarm } from './car';
36	import { drCars } from './cars';
37	import { drCamPlace, drCamDrag, type DrCam } from './camera';
38	import { drInputFromKeys, drBindDrop, DR_KEYS } from './keys';
39	import { drHudShow, drHudHide, drHudUpdate } from './hud';
40	import { drTouchBind } from './touch';
41	import { drSound } from './sound';
42	import { exNightStep } from '../nightShows';
43	import { show } from '../../bridges/dragon/effects';
44	import { exMulti } from '../multi';
45	import { exDrivers } from '../multi/remoteDrive';
46	import { exWatchShow, exWatchHide, exWatchRender, exFlyNotice } from '../multi/watch';
47	import type { SwingController } from '../../bridges/song-han/SwingController';
48	
49	const DR_SOLO_SLOT = -1;     // drCreate / drSpawnPose: lái một mình xuất phát ở giữa các chỗ của slot
50	const DR_SELF = 0;           // slot xe của mình trong drCars khi lái một mình (màu slot 0); có chỗ thật thì dùng slot được cấp
51	
52	/* Làm nóng shader của xe (D-018), như stroll/index.ts stRigSetWarm: hai biến thể (vẽ thẳng ra canvas ban ngày, vào render target của composer ban đêm),
53	   đèn / sương / bóng lấy từ cảnh chính, camera chính (đèn lọc theo lớp của nó). Nhóm làm nóng do car.ts dựng, không thêm vào scene */
54	drCarSetWarm(async (o: THREE.Object3D) => {
55	  const rt = renderer.getRenderTarget();
56	  renderer.setRenderTarget(null);
57	  const a = renderer.compileAsync(o, camera, scene);
58	  renderer.setRenderTarget(rt);
59	  await a;
60	  renderer.setRenderTarget(composer.readBuffer);
61	  const b = renderer.compileAsync(o, camera, scene);
62	  renderer.setRenderTarget(rt);
63	  await b;
64	});
65	
66	let net: DrNet | null = null;
67	let state: DrState | null = null;
68	let ctrl: SwingController | null = null;
69	const drKeys = new Set<string>();  // e.code đang giữ
70	const camS: DrCam = { yaw: 0, pitch: 0, idle: 0 };
71	const _inp: DrInput = { gas: 0, brake: 0, steer: 0, hand: false };   // đầu vào tái dùng mỗi khung
72	let selfSlot = DR_SELF;            // slot xe của mình trong drCars
73	let watching = false;              // đang xem xe người khác (hết chỗ lái hoặc vừa nhường chỗ): không có xe của mình, không đọc phím
74	let chased = false;                // camera đã bám xe được xem lần nào chưa (lần đầu đặt thẳng, không trượt từ xa)
75	let exit: () => void = () => {};   // thoát chung (explore.exit), dùng khi mất kết nối lúc đang xem
76	const _ws = { x: 0, z: 0, yaw: 0, v: 0 };   // xe đang xem đưa cho HUD (đồng hồ, bản đồ nhỏ), tái dùng mỗi khung
77	let touch: ReturnType<typeof drTouchBind> | null = null;   // điều khiển cảm ứng (setupDrive dựng)
78	const boxes: DrBox[] = [];         // hộp xe tự động gần xe, tái dùng mỗi khung (trNearby chỉ thêm phần tử khi phải nới)
79	let saved: { fov: number; explore: boolean; show: boolean } | null = null;   // thứ start() đổi, stop() trả lại: fov camera, lớp body 'explore' đã có từ trước chưa, show.on của Cầu Rồng (exNightStep đổi theo trời)
80	
81	const active = () => cam.mode === 'car' && state !== null;
82	const inMode = () => active() || watching;   // Esc và giao diện lái áp cho cả chế độ xem
83	const isField = (t: EventTarget | null) => !!t && /^(SELECT|INPUT|TEXTAREA)$/.test((t as HTMLElement).tagName || '');
84	
85	/* Mạng đường dựng lần đầu vào chế độ, giữ lại cho các lần sau; cổng nhịp quay theo cầu hiện tại.
86	   Dùng chung cho cả trang: chế độ xe máy (explore/bike) cũng gọi hàm này, không dựng net thứ hai (drCollectRuntime chỉ push) */
87	export function drEnsureNet(): DrNet {
88	  if (!net) {
89	    const n = drMakeNet(drBuildPads(), drBuildSolids());
90	    drCollectRuntime(n, (scene.getObjectByName('tp-houses') as THREE.InstancedMesh) || null);   // một lần cho mỗi net (chỉ push)
91	    net = n;                                                         // gán sau khi thu xong: thu lỗi thì lần vào sau thu lại từ đầu
92	  }
93	  if (ctrl) drSetGate(net, DR_GATE_SWING, ctrl.state !== 'CLOSED');
94	  return net;
95	}
96	
97	/* Giây (thời gian thật) còn lại tới lúc nhịp quay bắt đầu xoay (ROTATING_OPEN), giả sử nhịp không phải chờ xe tự động rời nhịp
98	   (spanClear đúng ngay: thời gian ngắn nhất); 0 khi nhịp đã / đang xoay hoặc cầu đóng: drEvacStep coi 0 là hết hạn (trượt trong evac.minTime), khác bỏ trống (không hạn) */
99	function drSwingBudget(c: SwingController): number {
100	  const T = c.cfg.timing, sp = c.speed > 0 ? c.speed : 1;
101	  if (c.state === 'STOP_TRAFFIC') return Math.max(0, T.amber + T.barrier - c.t + T.unlock) / sp;
102	  if (c.state === 'UNLOCK') return Math.max(0, T.unlock - c.t) / sp;
103	  return 0;
104	}
105	
106	/* Một bước: cổng nhịp quay, sơ tán / chuyển động, hình xe, camera, hiệu ứng đêm */
107	function advance(dt: number, inp: DrInput): void {
108	  if (ctrl) drSetGate(net!, DR_GATE_SWING, ctrl.state !== 'CLOSED');
109	  const s = state!;
110	  if (!drEvacStep(s, net!, dt, ctrl ? drSwingBudget(ctrl) : undefined)) drStep(s, inp, net!, boxes, trNearby(s.x, s.z, CONFIG.drive.ai.radius, boxes), dt);
111	  drCars.place(selfSlot, state!);
112	  drCamPlace(camera, state!, camS, net!, dt);
113	  controls.target.set(state!.x, state!.y, state!.z);   // tâm vùng bóng đổ (main.ts shadowCenter) theo xe
114	  const now = performance.now();
115	  exMulti.update(dt, now, null);     // xe người khác, người bay / đi dạo, nhãn tên; không làm gì khi lái một mình
116	  exMulti.updateDrive(now, state);   // gửi vị trí + vận tốc + góc lái khi đang giữ chỗ (kể cả lúc sơ tán)
117	  drHudUpdate(state!, exDrivers.dots()); drSound.update(state!.v);
118	  exNightStep(dt, false);
119	}
120	
121	/* Mỗi khung khi xem: xe người khác, nhãn, danh sách; camera sau xe được xem (hướng bám hướng xe đó), đồng hồ và bản đồ nhỏ theo xe đó. Không có ai thì giữ nguyên */
122	function watchStep(dt: number): void {
123	  if (ctrl) drSetGate(net!, DR_GATE_SWING, ctrl.state !== 'CLOSED');
124	  exMulti.update(dt, performance.now(), null);
125	  const w = exMulti.watchDriver();
126	  if (w) {
127	    drCamPlace(camera, w, camS, net!, dt, !chased); chased = true;
128	    controls.target.set(w.x, w.y, w.z);
129	    _ws.x = w.x; _ws.z = w.z; _ws.yaw = w.yaw; _ws.v = w.v;
130	    drHudUpdate(_ws, exDrivers.dots(w));
131	  }
132	  exNightStep(dt, false);
133	}
134	
135	/* Đổi phiên khi đang xem hoặc đang lái: vào lái, mất kết nối, bị thu hồi chỗ (như stOnMultiChange của đi dạo) */
136	function drOnMultiChange(): void {
137	  const s = exMulti.session; if (!s) return;
138	  if (watching) {
139	    if (s.phase === 'flying') { drive.start(); return; }   // chấp nhận lời mời: xuất phát như vào lái thường
140	    if (s.phase === 'solo') { try { sessionStorage.setItem('exMpNotice', 'lostDrive'); } catch { /* bộ nhớ bị chặn */ } exit(); return; }   // màn chọn đọc cờ này và hiện drLostChooser
141	    exWatchRender();
142	  } else if (active()) {
143	    if (s.phase === 'watching') { drive.startWatching(true); return; }   // chỗ bị thu hồi (rời máy): sang xem, camera giữ nguyên
144	    if (s.phase === 'solo' && s.notice === 'lost') exFlyNotice(s, 'drLost');   // vẫn lái, người khác đã biến mất
145	  }
146	}
147	
148	/* Xe đứng yên ở (x, z) hướng yaw, trạng thái mới từ drCreate (xóa trạng thái cọ tường); y bỏ trống thì lấy mặt đường cao nhất tại đó.
149	   Dùng cho test (__app.drive) và đặt lại vị trí */
150	function drPlaceAt(x: number, z: number, yaw: number, y?: number): void {
151	  if (!net) return;
152	  const s = drCreate(net, DR_SOLO_SLOT);
153	  let gy = -Infinity;
154	  for (const p of net.pads) {
155	    if (x < p.x0 || x > p.x1 || z < p.z0 || z > p.z1 || (p.gate !== undefined && net.closed.has(p.gate))) continue;
156	    gy = Math.max(gy, p.y(x, z));
157	  }
158	  s.x = x; s.z = z; s.yaw = yaw; s.y = y ?? (Number.isFinite(gy) ? gy : CONFIG.roadY);
159	  state = s;
160	  camS.yaw = 0; camS.pitch = 0; camS.idle = 0;
161	  drCars.place(selfSlot, s);
162	  drCamPlace(camera, s, camS, net, 0, true);
163	  controls.target.set(s.x, s.y, s.z);
164	}
165	
166	export const drive = {
167	  active,
168	  inMode,
169	  get watching(): boolean { return watching; },
170	  get state(): DrState | null { return state; },
171	  get net(): DrNet | null { return net; },
172	  get cam(): DrCam { return camS; },
173	  /* Tự lái (intro, D-045): khác null thì update() gọi auto(_inp) thay cho phím + cảm ứng, còi tắt; bên gán ghi vào _inp, không cấp phát */
174	  auto: null as ((inp: DrInput) => void) | null,
175	  /* Vào lái: một mình (không phiên / ngoại tuyến) hoặc với slot lái vừa được cấp (xuất phát theo slot, màu xe theo slot) */
176	  start(): void {
177	    if (watching) { watching = false; document.body.classList.remove('ex-watching'); exWatchHide(); }
178	    drUseBody(DR_CAR_BODY);   // thân va chạm ô tô (chế độ xe máy có thể đã đổi sang thân xe máy trong cùng trang)
179	    const n = drEnsureNet(), s = exMulti.session;
180	    const slot = s && s.kind === 'drive' && s.mySlot >= 0 ? s.mySlot : DR_SOLO_SLOT;
181	    if (s) exMulti.onChange = drOnMultiChange;
182	    selfSlot = slot >= 0 ? slot : DR_SELF;
183	    state = drCreate(n, slot);
184	    camS.yaw = 0; camS.pitch = 0; camS.idle = 0;
185	    exDrivers.setSelf(selfSlot);   // dựng xe của mình; drCars.group vào cảnh nhờ exDrivers.onCars (multi/index.ts)
186	    drCars.place(selfSlot, state);
187	    driveView.far = CONFIG.drive.tunnelFar;
188	    drKeys.clear(); touch?.reset();
189	    drHudShow(n); drSound.start();
190	    if (!saved) saved = { fov: camera.fov, explore: document.body.classList.contains('explore'), show: show.on };
191	    cam.flight.then = null; cam.mode = 'car'; controls.enabled = false;
192	    camera.fov = CONFIG.drive.cam.fov; onResize();   // onResize cập nhật ma trận chiếu và hệ số cỡ điểm theo fov mới
193	    drCamPlace(camera, state, camS, n, 0, true);
194	    controls.target.set(state.x, state.y, state.z);
195	    document.body.classList.add('explore', 'drive');
196	  },
197	  /* Chế độ xem bám xe người khác (hết chỗ lái, hoặc vừa nhường chỗ do rời máy): cam.mode = 'car' nhưng không có xe / trạng thái của mình, không đọc phím, không tiếng mô tơ;
198	     carry = true khi vừa nhường chỗ (camera đang ở sau xe cũ, trượt dần sang xe được xem). Không có phiên thì không làm gì */
199	  startWatching(carry = false): void {
200	    const s = exMulti.session; if (!s) return;
201	    drUseBody(DR_CAR_BODY);
202	    const n = drEnsureNet();
203	    state = null; watching = true; chased = carry;
204	    drKeys.clear(); touch?.reset(); drSound.stop();
205	    exDrivers.setSelf(-1);
206	    driveView.far = CONFIG.drive.tunnelFar;
207	    drHudShow(n);
208	    if (!saved) saved = { fov: camera.fov, explore: document.body.classList.contains('explore'), show: show.on };
209	    cam.flight.then = null; cam.mode = 'car'; controls.enabled = false;
210	    camera.fov = CONFIG.drive.cam.fov; onResize();
211	    document.body.classList.add('explore', 'drive', 'ex-watching');
212	    exMulti.onChange = drOnMultiChange;
213	    exWatchShow(s);
214	  },
215	  update(dt: number): void {
216	    if (watching) { watchStep(dt); return; }
217	    if (!active()) return;
218	    if (drive.auto) { drive.auto(_inp); drSound.horn(false); }
219	    else {
220	      drInputFromKeys(drKeys, _inp);
221	      if (touch) touch.read(_inp);   // gộp, không xóa phím
222	      drSound.horn(drKeys.has('KeyH'));
223	    }
224	    advance(dt, _inp);
225	  },
226	  /* Gọi ngay sau lệnh vẽ khung chính (main.ts); chỗ cho HUD / chụp ảnh của task sau */
227	  afterRender(): void { /* chưa có việc */ },
228	  /* Rời chế độ: trả mọi thứ đã đổi (explore.exit tải lại trang ngay sau), kể cả khi cam.mode đã bị chỗ khác đổi khỏi 'car' */
229	  stop(): void {
230	    if (state === null && !watching) return;
231	    state = null; drKeys.clear(); touch?.reset();
232	    if (watching) { watching = false; document.body.classList.remove('ex-watching'); exWatchHide(); }
233	    drHudHide(); drSound.stop();
234	    exDrivers.clear(); drCars.clear(); drCars.group.removeFromParent();
235	    driveView.far = 1;
236	    document.body.classList.remove('drive');
237	    if (saved) {
238	      if (!saved.explore) document.body.classList.remove('explore');
239	      camera.fov = saved.fov; onResize();                            // onResize tính lại ma trận chiếu và pScale theo fov cũ
240	      if (show.on !== saved.show) { show.on = saved.show; show.t = 0; }
241	      saved = null;
242	    }
243	    if (cam.mode === 'car') { cam.mode = 'orbit'; controls.enabled = true; }
244	  },
245	  /* Cho test: như update nhưng nhận đầu vào trực tiếp; đặt xe tại chỗ */
246	  step(dt: number, inp: DrInput): void { if (active()) advance(dt, inp); },
247	  placeAt: drPlaceAt,
248	  stats: drSceneStats,
249	  preload(): void { void drCarLoad(); }
250	};
251	
252	/* onExit: thoát chung (explore.exit), dùng khi mất kết nối lúc đang xem */
253	export function setupDrive(c: SwingController, onExit: () => void): void {
254	  ctrl = c; exit = onExit;
255	  window.addEventListener('keydown', (e) => {
256	    if (!active() || e.key === 'Escape') return;   // Esc do explore/index.ts xử lý (thoát chung)
257	    if (e.ctrlKey || e.metaKey || e.altKey) return;   // phím tắt trình duyệt không điều khiển xe, tránh kẹt phím
258	    if (isField(e.target)) return;                    // gõ trong ô nhập / chọn không điều khiển xe
259	    if (!DR_KEYS.has(e.code)) return;
260	    exMulti.activity();   // phím điều khiển (kể cả tự lặp) tính là còn đó
261	    if (e.code.startsWith('Arrow') || e.code === 'Space') e.preventDefault();   // không cuộn trang, Space không bấm nút đang focus
262	    drKeys.add(e.code);
263	  });
264	  window.addEventListener('keyup', (e) => {
265	    drKeys.delete(e.code);
266	    if (e.code === 'Space' && active() && !isField(e.target)) e.preventDefault();
267	  });
268	  const drop = drBindDrop(window, document, drKeys);
269	  window.addEventListener('focusin', (e) => { if (active() && isField(e.target)) { drop(); touch?.reset(); drSound.horn(false); } });
270	  /* Tab ẩn hoặc mất tiêu điểm: vòng khung có thể dừng nên tắt còi ngay (phím đã nhả ở drBindDrop, cảm ứng tự reset trong touch.ts) */

file.content:
/* ============================ Lái xe: điều phối chế độ (lái một mình, máy tính) ============================
   Nối mạng đường (net / roadData / solids / sceneSolids), chuyển động + va chạm (motion / collide), hình xe (car / cars),
   camera sau xe (camera) với vòng animate, phím, chuột, cảm ứng (touch), HUD (hud: đồng hồ, bản đồ nhỏ, gợi ý), tiếng mô tơ / còi (sound). Mẫu: explore/stroll/index.ts.
   `?explore=drive` vào thẳng, lái một mình; thẻ "Ô tô" ở màn chọn: có máy chủ thì qua sảnh 5 chỗ lái (phiên kind 'drive'), không thì lái một mình.
   Esc và nút Thoát dùng explore.exit() (tải lại trang, D-020); trước đó drive.stop() trả lại các thứ đã đổi.
   - Mạng đường dựng MỘT lần ở lần đầu vào chế độ và giữ lại: ô tĩnh + vật cản tĩnh + nhà / chân đế thu từ cảnh (drCollectRuntime chỉ push,
     gọi hai lần sẽ nhân đôi vật cản). Chỉ đọc cảnh, sau mọi rand().
   - Barie Cầu sông Hàn: cổng DR_GATE_SWING của ô nhịp quay đóng khi cầu rời CLOSED (mỗi khung); không tự quay, không tăng tốc quay (như đi dạo).
     Xe đang chạm nhịp quay lúc đó được sơ tán ra ngoài barie gần nhất (motion.ts drEvacStep), gói trong thời gian còn lại trước khi nhịp xoay
     (drSwingBudget: coi như nhịp không phải chờ xe tự động rời nhịp, tức thời gian ngắn nhất).
   - Xe tự động: mỗi khung lấy hộp các xe đang hiện trong bán kính CONFIG.drive.ai.radius (common/trafficQuery.ts trNearby, mảng tái dùng);
     người chơi lao vào thì bị chặn, xe tự động chạy tới thì đi xuyên (collide.ts drMove).
   - Ban đêm Cầu Rồng tự phun như khi đi dạo (exNightStep, swing = false).
   - Hầm: driveView.far = CONFIG.drive.tunnelFar khi đang lái để mặt đường hầm hiện ở nút giao với hai đường dọc mới; thoát trả 1.
   - Xe của mình nằm trong drCars ở slot của mình (màu theo slot, multiParams.colors) hoặc slot 0 khi lái một mình; xe và bánh chỉ vào cảnh khi có xe (multi/index.ts gắn drCars.group
     theo exDrivers.onCars), góc nhìn cũ không thêm lệnh vẽ.
   - Nhiều người (exMulti, phiên kind 'drive'): xuất phát theo slot, gửi vị trí + vận tốc + góc lái sendHz lần/s (cả lúc đang sơ tán khỏi nhịp quay); xe người khác (exDrivers) không tham gia va chạm
     (chỉ vẽ, nhãn tên, chấm trên bản đồ nhỏ). Hết chỗ lái thì chế độ xem (startWatching): camera sau xe được xem, không điều khiển, đồng hồ + bản đồ theo xe đó; rời máy thì nhường chỗ sang xem.
   - Phím theo e.code (keys.ts), chỉ ghi khi đang lái, bỏ qua ô nhập và tổ hợp Ctrl / Meta / Alt; blur, ẩn tab, focus vào ô nhập thì nhả hết.
   - Cảm ứng (touch.ts, #drHud): đọc SAU phím và gộp (giá trị có độ lớn lớn hơn), không xóa phím trên máy lai; reset() cùng chỗ nhả phím. Phím H: còi.
   Mỗi khung không cấp phát (D-018). */
import type * as THREE from 'three';
import { scene, camera, controls, canvas, renderer } from '../../core/renderer';
import { composer, onResize } from '../../core/postprocessing';
import { cam } from '../../views/state';
import { CONFIG } from '../../config';
import { driveView } from '../../environment/driveRoads';
import { drMakeNet, drSetGate, type DrNet } from './net';
import { drBuildPads, DR_GATE_SWING } from './roadData';
import { drBuildSolids } from './solids';
import { drCollectRuntime, drSceneStats } from './sceneSolids';
import { drCreate, drStep, drEvacStep, type DrState, type DrInput } from './motion';
import { trNearby } from '../../common/trafficQuery';
import { drUseBody, DR_CAR_BODY, type DrBox } from './collide';
import { drCarLoad, drCarSetWarm } from './car';
import { drCars } from './cars';
import { drCamPlace, drCamDrag, type DrCam } from './camera';
import { drInputFromKeys, drBindDrop, DR_KEYS } from './keys';
import { drHudShow, drHudHide, drHudUpdate } from './hud';
import { drTouchBind } from './touch';
import { drSound } from './sound';
import { exNightStep } from '../nightShows';
import { show } from '../../bridges/dragon/effects';
import { exMulti } from '../multi';
import { exDrivers } from '../multi/remoteDrive';
import { exWatchShow, exWatchHide, exWatchRender, exFlyNotice } from '../multi/watch';
import type { SwingController } from '../../bridges/song-han/SwingController';

const DR_SOLO_SLOT = -1;     // drCreate / drSpawnPose: lái một mình xuất phát ở giữa các chỗ của slot
const DR_SELF = 0;           // slot xe của mình trong drCars khi lái một mình (màu slot 0); có chỗ thật thì dùng slot được cấp

/* Làm nóng shader của xe (D-018), như stroll/index.ts stRigSetWarm: hai biến thể (vẽ thẳng ra canvas ban ngày, vào render target của composer ban đêm),
   đèn / sương / bóng lấy từ cảnh chính, camera chính (đèn lọc theo lớp của nó). Nhóm làm nóng do car.ts dựng, không thêm vào scene */
drCarSetWarm(async (o: THREE.Object3D) => {
  const rt = renderer.getRenderTarget();
  renderer.setRenderTarget(null);
  const a = renderer.compileAsync(o, camera, scene);
  renderer.setRenderTarget(rt);
  await a;
  renderer.setRenderTarget(composer.readBuffer);
  const b = renderer.compileAsync(o, camera, scene);
  renderer.setRenderTarget(rt);
  await b;
});

let net: DrNet | null = null;
let state: DrState | null = null;
let ctrl: SwingController | null = null;
const drKeys = new Set<string>();  // e.code đang giữ
const camS: DrCam = { yaw: 0, pitch: 0, idle: 0 };
const _inp: DrInput = { gas: 0, brake: 0, steer: 0, hand: false };   // đầu vào tái dùng mỗi khung
let selfSlot = DR_SELF;            // slot xe của mình trong drCars
let watching = false;              // đang xem xe người khác (hết chỗ lái hoặc vừa nhường chỗ): không có xe của mình, không đọc phím
let chased = false;                // camera đã bám xe được xem lần nào chưa (lần đầu đặt thẳng, không trượt từ xa)
let exit: () => void = () => {};   // thoát chung (explore.exit), dùng khi mất kết nối lúc đang xem
const _ws = { x: 0, z: 0, yaw: 0, v: 0 };   // xe đang xem đưa cho HUD (đồng hồ, bản đồ nhỏ), tái dùng mỗi khung
let touch: ReturnType<typeof drTouchBind> | null = null;   // điều khiển cảm ứng (setupDrive dựng)
const boxes: DrBox[] = [];         // hộp xe tự động gần xe, tái dùng mỗi khung (trNearby chỉ thêm phần tử khi phải nới)
let saved: { fov: number; explore: boolean; show: boolean } | null = null;   // thứ start() đổi, stop() trả lại: fov camera, lớp body 'explore' đã có từ trước chưa, show.on của Cầu Rồng (exNightStep đổi theo trời)

const active = () => cam.mode === 'car' && state !== null;
const inMode = () => active() || watching;   // Esc và giao diện lái áp cho cả chế độ xem
const isField = (t: EventTarget | null) => !!t && /^(SELECT|INPUT|TEXTAREA)$/.test((t as HTMLElement).tagName || '');

/* Mạng đường dựng lần đầu vào chế độ, giữ lại cho các lần sau; cổng nhịp quay theo cầu hiện tại.
   Dùng chung cho cả trang: chế độ xe máy (explore/bike) cũng gọi hàm này, không dựng net thứ hai (drCollectRuntime chỉ push) */
export function drEnsureNet(): DrNet {
  if (!net) {
    const n = drMakeNet(drBuildPads(), drBuildSolids());
    drCollectRuntime(n, (scene.getObjectByName('tp-houses') as THREE.InstancedMesh) || null);   // một lần cho mỗi net (chỉ push)
    net = n;                                                         // gán sau khi thu xong: thu lỗi thì lần vào sau thu lại từ đầu
  }
  if (ctrl) drSetGate(net, DR_GATE_SWING, ctrl.state !== 'CLOSED');
  return net;
}

/* Giây (thời gian thật) còn lại tới lúc nhịp quay bắt đầu xoay (ROTATING_OPEN), giả sử nhịp không phải chờ xe tự động rời nhịp
   (spanClear đúng ngay: thời gian ngắn nhất); 0 khi nhịp đã / đang xoay hoặc cầu đóng: drEvacStep coi 0 là hết hạn (trượt trong evac.minTime), khác bỏ trống (không hạn) */
function drSwingBudget(c: SwingController): number {
  const T = c.cfg.timing, sp = c.speed > 0 ? c.speed : 1;
  if (c.state === 'STOP_TRAFFIC') return Math.max(0, T.amber + T.barrier - c.t + T.unlock) / sp;
  if (c.state === 'UNLOCK') return Math.max(0, T.unlock - c.t) / sp;
  return 0;
}

/* Một bước: cổng nhịp quay, sơ tán / chuyển động, hình xe, camera, hiệu ứng đêm */
function advance(dt: number, inp: DrInput): void {
  if (ctrl) drSetGate(net!, DR_GATE_SWING, ctrl.state !== 'CLOSED');
  const s = state!;
  if (!drEvacStep(s, net!, dt, ctrl ? drSwingBudget(ctrl) : undefined)) drStep(s, inp, net!, boxes, trNearby(s.x, s.z, CONFIG.drive.ai.radius, boxes), dt);
  drCars.place(selfSlot, state!);
  drCamPlace(camera, state!, camS, net!, dt);
  controls.target.set(state!.x, state!.y, state!.z);   // tâm vùng bóng đổ (main.ts shadowCenter) theo xe
  const now = performance.now();
  exMulti.update(dt, now, null);     // xe người khác, người bay / đi dạo, nhãn tên; không làm gì khi lái một mình
  exMulti.updateDrive(now, state);   // gửi vị trí + vận tốc + góc lái khi đang giữ chỗ (kể cả lúc sơ tán)
  drHudUpdate(state!, exDrivers.dots()); drSound.update(state!.v);
  exNightStep(dt, false);
}

/* Mỗi khung khi xem: xe người khác, nhãn, danh sách; camera sau xe được xem (hướng bám hướng xe đó), đồng hồ và bản đồ nhỏ theo xe đó. Không có ai thì giữ nguyên */
function watchStep(dt: number): void {
  if (ctrl) drSetGate(net!, DR_GATE_SWING, ctrl.state !== 'CLOSED');
  exMulti.update(dt, performance.now(), null);
  const w = exMulti.watchDriver();
  if (w) {
    drCamPlace(camera, w, camS, net!, dt, !chased); chased = true;
    controls.target.set(w.x, w.y, w.z);
    _ws.x = w.x; _ws.z = w.z; _ws.yaw = w.yaw; _ws.v = w.v;
    drHudUpdate(_ws, exDrivers.dots(w));
  }
  exNightStep(dt, false);
}

/* Đổi phiên khi đang xem hoặc đang lái: vào lái, mất kết nối, bị thu hồi chỗ (như stOnMultiChange của đi dạo) */
function drOnMultiChange(): void {
  const s = exMulti.session; if (!s) return;
  if (watching) {
    if (s.phase === 'flying') { drive.start(); return; }   // chấp nhận lời mời: xuất phát như vào lái thường
    if (s.phase === 'solo') { try { sessionStorage.setItem('exMpNotice', 'lostDrive'); } catch { /* bộ nhớ bị chặn */ } exit(); return; }   // màn chọn đọc cờ này và hiện drLostChooser
    exWatchRender();
  } else if (active()) {
    if (s.phase === 'watching') { drive.startWatching(true); return; }   // chỗ bị thu hồi (rời máy): sang xem, camera giữ nguyên
    if (s.phase === 'solo' && s.notice === 'lost') exFlyNotice(s, 'drLost');   // vẫn lái, người khác đã biến mất
  }
}

/* Xe đứng yên ở (x, z) hướng yaw, trạng thái mới từ drCreate (xóa trạng thái cọ tường); y bỏ trống thì lấy mặt đường cao nhất tại đó.
   Dùng cho test (__app.drive) và đặt lại vị trí */
function drPlaceAt(x: number, z: number, yaw: number, y?: number): void {
  if (!net) return;
  const s = drCreate(net, DR_SOLO_SLOT);
  let gy = -Infinity;
  for (const p of net.pads) {
    if (x < p.x0 || x > p.x1 || z < p.z0 || z > p.z1 || (p.gate !== undefined && net.closed.has(p.gate))) continue;
    gy = Math.max(gy, p.y(x, z));
  }
  s.x = x; s.z = z; s.yaw = yaw; s.y = y ?? (Number.isFinite(gy) ? gy : CONFIG.roadY);
  state = s;
  camS.yaw = 0; camS.pitch = 0; camS.idle = 0;
  drCars.place(selfSlot, s);
  drCamPlace(camera, s, camS, net, 0, true);
  controls.target.set(s.x, s.y, s.z);
}

export const drive = {
  active,
  inMode,
  get watching(): boolean { return watching; },
  get state(): DrState | null { return state; },
  get net(): DrNet | null { return net; },
  get cam(): DrCam { return camS; },
  /* Tự lái (intro, D-045): khác null thì update() gọi auto(_inp) thay cho phím + cảm ứng, còi tắt; bên gán ghi vào _inp, không cấp phát */
  auto: null as ((inp: DrInput) => void) | null,
  /* Vào lái: một mình (không phiên / ngoại tuyến) hoặc với slot lái vừa được cấp (xuất phát theo slot, màu xe theo slot) */
  start(): void {
    if (watching) { watching = false; document.body.classList.remove('ex-watching'); exWatchHide(); }
    drUseBody(DR_CAR_BODY);   // thân va chạm ô tô (chế độ xe máy có thể đã đổi sang thân xe máy trong cùng trang)
    const n = drEnsureNet(), s = exMulti.session;
    const slot = s && s.kind === 'drive' && s.mySlot >= 0 ? s.mySlot : DR_SOLO_SLOT;
    if (s) exMulti.onChange = drOnMultiChange;
    selfSlot = slot >= 0 ? slot : DR_SELF;
    state = drCreate(n, slot);
    camS.yaw = 0; camS.pitch = 0; camS.idle = 0;
    exDrivers.setSelf(selfSlot);   // dựng xe của mình; drCars.group vào cảnh nhờ exDrivers.onCars (multi/index.ts)
    drCars.place(selfSlot, state);
    driveView.far = CONFIG.drive.tunnelFar;
    drKeys.clear(); touch?.reset();
    drHudShow(n); drSound.start();
    if (!saved) saved = { fov: camera.fov, explore: document.body.classList.contains('explore'), show: show.on };
    cam.flight.then = null; cam.mode = 'car'; controls.enabled = false;
    camera.fov = CONFIG.drive.cam.fov; onResize();   // onResize cập nhật ma trận chiếu và hệ số cỡ điểm theo fov mới
    drCamPlace(camera, state, camS, n, 0, true);
    controls.target.set(state.x, state.y, state.z);
    document.body.classList.add('explore', 'drive');
  },
  /* Chế độ xem bám xe người khác (hết chỗ lái, hoặc vừa nhường chỗ do rời máy): cam.mode = 'car' nhưng không có xe / trạng thái của mình, không đọc phím, không tiếng mô tơ;
     carry = true khi vừa nhường chỗ (camera đang ở sau xe cũ, trượt dần sang xe được xem). Không có phiên thì không làm gì */
  startWatching(carry = false): void {
    const s = exMulti.session; if (!s) return;
    drUseBody(DR_CAR_BODY);
    const n = drEnsureNet();
    state = null; watching = true; chased = carry;
    drKeys.clear(); touch?.reset(); drSound.stop();
    exDrivers.setSelf(-1);
    driveView.far = CONFIG.drive.tunnelFar;
    drHudShow(n);
    if (!saved) saved = { fov: camera.fov, explore: document.body.classList.contains('explore'), show: show.on };
    cam.flight.then = null; cam.mode = 'car'; controls.enabled = false;
    camera.fov = CONFIG.drive.cam.fov; onResize();
    document.body.classList.add('explore', 'drive', 'ex-watching');
    exMulti.onChange = drOnMultiChange;
    exWatchShow(s);
  },
  update(dt: number): void {
    if (watching) { watchStep(dt); return; }
    if (!active()) return;
    if (drive.auto) { drive.auto(_inp); drSound.horn(false); }
    else {
      drInputFromKeys(drKeys, _inp);
      if (touch) touch.read(_inp);   // gộp, không xóa phím
      drSound.horn(drKeys.has('KeyH'));
    }
    advance(dt, _inp);
  },
  /* Gọi ngay sau lệnh vẽ khung chính (main.ts); chỗ cho HUD / chụp ảnh của task sau */
  afterRender(): void { /* chưa có việc */ },
  /* Rời chế độ: trả mọi thứ đã đổi (explore.exit tải lại trang ngay sau), kể cả khi cam.mode đã bị chỗ khác đổi khỏi 'car' */
  stop(): void {
    if (state === null && !watching) return;
    state = null; drKeys.clear(); touch?.reset();
    if (watching) { watching = false; document.body.classList.remove('ex-watching'); exWatchHide(); }
    drHudHide(); drSound.stop();
    exDrivers.clear(); drCars.clear(); drCars.group.removeFromParent();
    driveView.far = 1;
    document.body.classList.remove('drive');
    if (saved) {
      if (!saved.explore) document.body.classList.remove('explore');
      camera.fov = saved.fov; onResize();                            // onResize tính lại ma trận chiếu và pScale theo fov cũ
      if (show.on !== saved.show) { show.on = saved.show; show.t = 0; }
      saved = null;
    }
    if (cam.mode === 'car') { cam.mode = 'orbit'; controls.enabled = true; }
  },
  /* Cho test: như update nhưng nhận đầu vào trực tiếp; đặt xe tại chỗ */
  step(dt: number, inp: DrInput): void { if (active()) advance(dt, inp); },
  placeAt: drPlaceAt,
  stats: drSceneStats,
  preload(): void { void drCarLoad(); }
};

/* onExit: thoát chung (explore.exit), dùng khi mất kết nối lúc đang xem */
export function setupDrive(c: SwingController, onExit: () => void): void {
  ctrl = c; exit = onExit;
  window.addEventListener('keydown', (e) => {
    if (!active() || e.key === 'Escape') return;   // Esc do explore/index.ts xử lý (thoát chung)
    if (e.ctrlKey || e.metaKey || e.altKey) return;   // phím tắt trình duyệt không điều khiển xe, tránh kẹt phím
    if (isField(e.target)) return;                    // gõ trong ô nhập / chọn không điều khiển xe
    if (!DR_KEYS.has(e.code)) return;
    exMulti.activity();   // phím điều khiển (kể cả tự lặp) tính là còn đó
    if (e.code.startsWith('Arrow') || e.code === 'Space') e.preventDefault();   // không cuộn trang, Space không bấm nút đang focus
    drKeys.add(e.code);
  });
  window.addEventListener('keyup', (e) => {
    drKeys.delete(e.code);
    if (e.code === 'Space' && active() && !isField(e.target)) e.preventDefault();
  });
  const drop = drBindDrop(window, document, drKeys);
  window.addEventListener('focusin', (e) => { if (active() && isField(e.target)) { drop(); touch?.reset(); drSound.horn(false); } });
  /* Tab ẩn hoặc mất tiêu điểm: vòng khung có thể dừng nên tắt còi ngay (phím đã nhả ở drBindDrop, cảm ứng tự reset trong touch.ts) */

