243	function bkPlaceAt(x: number, z: number, yaw: number, y?: number): void {
244	  if (!net || !model) return;
245	  const s = bkCreate(net, BK_SOLO_SLOT);
246	  let gy = -Infinity;
247	  for (const p of net.pads) {
