249	    gy = Math.max(gy, p.y(x, z));
250	  }
251	  s.x = x; s.z = z; s.yaw = yaw; s.y = y ?? (Number.isFinite(gy) ? gy : CONFIG.roadY);
252	  bkPitch(s, net);
253	  state = s;
254	  bkCamReset();
255	  model.place(s);
256	  riderStep(s, 0);
257	  riderEye();
