    if (active || waitMo || !deps) return;
    sset(SS, I.seenKey, '1');
    plPreload(); drive.preload(); bike.preload(); stAvatars.preload();            // mô hình nạp trước; chưa về thì chế độ dùng hình tạm có sẵn
    const loading = document.getElementById('loading');
