const sleep = (ms) => new Promise((ok) => setTimeout(ok, ms));
const problems = [];
const check = (n, ok, extra = '') => { if (!ok) problems.push(n); console.log(`${ok ? 'đạt ' : 'LỖI '} ${n} ${extra}`); };
const only = process.argv[2] || 'all';

const srv = await serveDir(ROOT + 'dist');
const browser = await launch();
try {
  const { page, errors } = await openApp(browser, srv.url + '?intro', { width: 1280, height: 720 });
  await page.waitForFunction(() => window.__app.intro.active, null, { timeout: 30000 });
  check('intro tự phát ở ?test&intro', true);
  const st = () => page.evaluate(() => { const a = window.__app; return { scene: a.intro.sceneId, t: +a.intro.clock.t.toFixed(2), mode: a.cam.mode, target: +a.dayNight.target.toFixed(2), night: +a.dayNight.night.toFixed(2), show: a.show ? a.show.on : null, sw: a.songHan.ctrl.state, cam: a.camera.position.toArray().map((v) => Math.round(v)), fov: a.camera.fov, calls: a.renderer.info.render.calls,
    car: a.drive.state ? [a.drive.state.x, a.drive.state.z, a.drive.state.v].map((v) => +v.toFixed(1)) : null, bike: a.bike.state ? [a.bike.state.x, a.bike.state.z, a.bike.state.v].map((v) => +v.toFixed(1)) : null, view: a.bike.view,
    walk: a.stroll.stroll.state ? [a.stroll.stroll.state.x, a.stroll.stroll.state.z].map((v) => +v.toFixed(1)) : null, gl: a.explore.state ? a.explore.state.pos.toArray().map((v) => Math.round(v)) : null }; });
  const ids = ['welcome', 'glider', 'car', 'bike', 'walk', 'daynight', 'dragon', 'swing', 'finale'];
  const durs = [7, 4.5, 4.5, 4.5, 4.5, 8, 9, 9, 6];
  if (only === 'all' || only === 'shots') {
    for (let i = 0; i < 9; i++) {
      await page.evaluate((i) => window.__app.intro.seek(i), i);
      const marks = i === 0 ? [1.2, 4, 6.8] : i === 5 ? [1.2, 4, 7.4] : i === 6 ? [1.2, 3, 7] : i === 7 ? [1.2, 4.5, 8.4] : i === 8 ? [1.2, 3.5, 7] : [1.2, 3, 4.2];
      let last = 0;
      for (const m of marks) {
        await page.waitForFunction(([i, m]) => window.__app.intro.clock.i !== i || window.__app.intro.clock.t >= m || window.__app.intro.clock.done, [i, m], { timeout: 30000 });
        const s = await st();
        await page.screenshot({ path: `${OUT}${i}-${ids[i]}-${m}.png` });
        console.log(`  ${i} ${ids[i]} @${m}:`, JSON.stringify(s));
        last = m;
      }
    }
  }
  if (only === 'all' || only === 'ctl') {
    // tạm dừng ở nhịp ô tô
    await page.evaluate(() => { const a = window.__app; if (!a.intro.active) a.intro.play(); a.intro.seek(2); });
    await page.waitForFunction(() => window.__app.intro.clock.t >= 2, null, { timeout: 30000 });
    await page.evaluate(() => window.__app.intro.pause(true));
    const a1 = await st(); await sleep(1200); const a2 = await st();
    check('tạm dừng: clock.t đứng', a1.t === a2.t, `${a1.t} ${a2.t}`);
    check('tạm dừng: xe đứng', JSON.stringify(a1.car) === JSON.stringify(a2.car), `${a1.car} ${a2.car}`);
    check('tạm dừng: nút ▶ aria-pressed', await page.evaluate(() => document.getElementById('inPause').getAttribute('aria-pressed') === 'true'));
    await page.keyboard.press(' ');
    const a3 = await st(); await sleep(500); const a4 = await st();
    check('Space tiếp tục', a4.t > a3.t, `${a3.t} → ${a4.t}`);
    // Esc ở nhịp ô tô
    await page.evaluate(() => { window.__mark = 1; window.__app.intro.seek(2); });
    await page.waitForFunction(() => window.__app.intro.clock.t >= 1.5, null, { timeout: 30000 });
    await page.keyboard.press('KeyW');
    await page.keyboard.press('Escape');
    await frames(page, 3);
    const e = await page.evaluate(() => { const a = window.__app; return { mark: window.__mark, active: a.intro.active, chooser: !document.getElementById('chooser').hidden, intro: document.getElementById('intro').hidden, mode: a.cam.mode, fov: a.camera.fov, near: a.camera.near, body: document.body.className, ctl: a.controls.enabled, show: a.show?.on }; });
    console.log('  sau Esc:', JSON.stringify(e));
    check('Esc: không tải lại trang', e.mark === 1);
    check('Esc: intro kết thúc, #intro ẩn', !e.active && e.intro);
    check('Esc: màn chọn hiện', e.chooser);
    check('Esc: cam.mode orbit + controls', e.mode === 'orbit' && e.ctl);
    check('Esc: fov 50, near 0.5', e.fov === 50 && e.near === 0.5);
    check('Esc: body sạch', !/\b(intro|explore|drive|bike|stroll)\b/.test(e.body), e.body);
    // bỏ qua khi cầu đang quay
    await page.evaluate(() => { document.querySelector('#chooser') && (document.getElementById('chooser').hidden = true); window.__app.intro.play(); window.__app.intro.seek(7); });
    await page.waitForFunction(() => /ROTATING_OPEN|OPEN/.test(window.__app.songHan.ctrl.state), null, { timeout: 30000 });
    const s0 = await st();
    await page.evaluate(() => window.__app.intro.skip());
    const t0 = Date.now();
    let closed = false;
    try { await page.waitForFunction(() => window.__app.songHan.ctrl.state === 'CLOSED', null, { timeout: 20000 }); closed = true; } catch { /* hết giờ */ }
    check('bỏ qua lúc cầu quay: cầu về CLOSED ≤ 20 s', closed, `từ ${s0.sw}, ${((Date.now() - t0) / 1000).toFixed(1)} s`);
    // nút Ô tô ở nhịp cuối
    await page.evaluate(() => { document.getElementById('chooser').hidden = true; window.__app.intro.play(); window.__app.intro.seek(8); });
    await sleep(1200);
    await page.click('#inEnd button[data-in-pick="car"]');
    await frames(page, 5);
    const c = await page.evaluate(() => { const a = window.__app; return { mode: a.cam.mode, act: a.drive.active(), intro: a.intro.active, chooser: !document.getElementById('chooser').hidden, body: document.body.className }; });
    console.log('  sau nút Ô tô:', JSON.stringify(c));
    check('finale Ô tô: vào chế độ lái thật', c.mode === 'car' && c.act && !c.intro && !c.chooser);
    await page.screenshot({ path: `${OUT}9-finale-car.png` });
    check('console sạch (trang intro)', errors.length === 0, errors.join(' | '));
    await page.close();
  }
  if (only === 'all' || only === 'chooser') {
    const { page: p2, errors: e2 } = await openApp(browser, srv.url + '?chooser', { width: 1280, height: 720 });
    await frames(p2, 10);
    const r = await p2.evaluate(() => ({ active: window.__app.intro.active, intro: document.getElementById('intro').hidden, chooser: !document.getElementById('chooser').hidden }));
    check('?test&chooser: không intro, màn chọn hiện', !r.active && r.intro && r.chooser, JSON.stringify(r));
    check('console sạch (trang chooser)', e2.length === 0, e2.join(' | '));
    await p2.close();
  }
} finally { await browser.close(); srv.close(); }
console.log(problems.length ? `LỖI: ${problems.join('; ')}` : 'TẤT CẢ ĐẠT');

