// Thử tư thế camera nhịp dragon (tạm). TEST_REAL_GPU=1 node intro-probe.mjs
const ROOT = 'D:/2026 - Tuan/danang-vite/.worktrees/intro-dien-anh/';
const { serveDir, launch, openApp, frames } = await import('file:///' + ROOT + 'tests/lib.mjs');
const OUT = ROOT + 'tests/screens/intro/';
const poses = JSON.parse(process.argv[2]);
const scene = +(process.argv[3] || 6), at = +(process.argv[4] || 2);
const srv = await serveDir(ROOT + 'dist');
const browser = await launch();
try {
  const { page } = await openApp(browser, srv.url + '?intro', { width: 1280, height: 720 });
  await page.waitForFunction(() => window.__app.intro.active);
  await page.evaluate((s) => window.__app.intro.seek(s), scene);
  await page.waitForFunction((at) => window.__app.intro.clock.t >= at, at);
  await page.evaluate(() => { window.__app.intro.pause(true); document.getElementById('intro').style.visibility = 'hidden'; });
  for (let k = 0; k < poses.length; k++) {
    const [p, t] = poses[k];
    await page.evaluate(([p, t]) => { const a = window.__app; a.camera.position.set(...p); a.controls.target.set(...t); a.camera.lookAt(a.controls.target); }, [p, t]);
    await frames(page, 4);
    await page.screenshot({ path: `${OUT}probe-${k}.png` });
  }
} finally { await browser.close(); srv.close(); }

