// Kiểm khói intro (D-045 Task 4) — script tạm, không commit. TEST_REAL_GPU=1 node intro-smoke.mjs [only]
import fs from 'node:fs';
const ROOT = 'D:/2026 - Tuan/danang-vite/.worktrees/intro-dien-anh/';
const { serveDir, launch, openApp, frames } = await import('file:///' + ROOT + 'tests/lib.mjs');
const OUT = ROOT + 'tests/screens/intro/';
fs.mkdirSync(OUT, { recursive: true });
const sleep = (ms) => new Promise((ok) => setTimeout(ok, ms));
const problems = [];
const check = (n, ok, extra = '') => { if (!ok) problems.push(n); console.log(`${ok ? 'đạt ' : 'LỖI '} ${n} ${extra}`); };
const only = process.argv[2] || 'all';

const srv = await serveDir(ROOT + 'dist');
const browser = await launch();
try {
  const { page, errors } = await openApp(browser, srv.url + '?intro', { width: 1280, height: 720 });
  await page.waitForFunction(() => window.__app.intro.active, null, { timeout: 30000 });
  check('intro tự phát ở ?test&intro', true);
  const st = () => page.evaluate(() => { const a = window.__app; return { scene: a.intro.sceneId, t: +a.intro.clock.t.toFixed(2), mode: a.cam.mode, target: +a.dayNight.target.toFixed(2), night: +a.dayNight.night.toFixed(2), show: a.show ? a.show.on : null, sw: a.songHan.ctrl.state, cam: a.camera.position.toArray().map((v) => Math.round(v)), fov: a.camera.fov, calls: a.renderer.info.render.calls,
    car: a.drive.state ? [a.drive.state.x, a.drive.state.z, a.drive.state.v].map((v) => +v.toFixed(1)) : null, bike: a.bike.state ? [a.bike.state.x, a.bike.state.z, a.bike.state.v].map((v) => +v.toFixed(1)) : null, view: a.bike.view,
    walk: a.stroll.stroll.state ? [a.stroll.stroll.state.x, a.stroll.stroll.state.z].map((v) => +v.toFixed(1)) : null, gl: a.explore.state ? a.explore.state.pos.toArray().map((v) => Math.round(v)) : null }; });
  const ids = ['welcome', 'glider', 'car', 'bike', 'walk', 'daynight', 'dragon', 'swing', 'finale'];
  const durs = [7, 4.5, 4.5, 4.5, 4.5, 8, 9, 9, 6];
  if (only === 'all' || only === 'shots') {
    for (let i = 0; i < 9; i++) {
      await page.evaluate((i) => window.__app.intro.seek(i), i);
      const marks = i === 0 ? [1.2, 4, 6.8] : i === 5 ? [1.2, 4, 7.4] : i === 6 ? [1.2, 3, 7] : i === 7 ? [1.2, 4.5, 8.4] : i === 8 ? [1.2, 3.5, 7] : [1.2, 3, 4.2];
      let last = 0;
      for (const m of marks) {
        await page.waitForFunction(([i, m]) => window.__app.intro.clock.i !== i || window.__app.intro.clock.t >= m || window.__app.intro.clock.done, [i, m], { timeout: 30000 });
        const s = await st();
        await page.screenshot({ path: `${OUT}${i}-${ids[i]}-${m}.png` });
        console.log(`  ${i} ${ids[i]} @${m}:`, JSON.stringify(s));
        last = m;
      }
    }
  }
  if (only === 'all' || only === 'ctl') {
    // tạm dừng ở nhịp ô tô
    await page.evaluate(() => { const a = window.__app; if (!a.intro.active) a.intro.play(); a.intro.seek(2); });
    await page.waitForFunction(() => window.__app.intro.clock.t >= 2, null, { timeout: 30000 });
    await page.evaluate(() => window.__app.intro.pause(true));
    const a1 = await st(); await sleep(1200); const a2 = await st();
