const ROOT = 'D:/2026 - Tuan/danang-vite/.worktrees/intro-dien-anh/';
const { serveDir, launch, openApp } = await import('file:///' + ROOT + 'tests/lib.mjs');
const sleep = (ms) => new Promise((ok) => setTimeout(ok, ms));
const srv = await serveDir(ROOT + 'dist');
const browser = await launch();
const variants = process.argv.slice(2);
try {
  for (const v of variants) {
    const errs = [];
    const { page } = await openApp(browser, srv.url + (v === 'intro' ? '?intro' : ''), { width: 1280, height: 720, before: (pg) => pg.on('pageerror', (e) => errs.push(e.message)) });
    await page.evaluate((v) => {
      const a = window.__app;
      if (v === 'all') { a.drive.preload(); a.bike.preload(); a.stroll.avatars.preload(); a.explore.start(); a.explore.stop(); }
      if (v === 'car') a.drive.preload();
      if (v === 'bike') a.bike.preload();
      if (v === 'walk') a.stroll.avatars.preload();
      if (v === 'glider') { a.explore.start(); a.explore.stop(); }
